package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.node.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import java.lang.reflect.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B10ReadDisplayMysqlTest extends TestCase {
    private A1TestFixture f;private AgentStore store;private long book;private ObjectNode snapshot;
    protected void setUp()throws Exception{f=new A1TestFixture();store=new AgentStore(f.db);ControlledWriteService writes=new ControlledWriteService(store,f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());A1TestFixture.inject(writes,"enabled",true);A1TestFixture.inject(f.runs,"controlled",writes);A1TestFixture.inject(f.runs,"readDisplay",true);A1TestFixture.inject(f.runs,"timeoutMs",900000L);A1TestFixture.inject(f.guard,"enabled",true);snapshot=B10ReadDisplayTest.snapshot();book=f.seed(snapshot.toString());}
    protected void tearDown(){f.close();}
    private ObjectNode request(){ObjectNode ws=f.runs.workspace(book,1),q=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("expectedRevision",ws.path("revision").asText()).put("expectedDraftVersion",-1).put("expectedBranchVersion",0).put("loadedRevision",ws.path("loadedRevision").asText()).put("activeSheetId","s").put("goal","Read display");q.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","A1:D4")));return q;}
    private void reject(Runnable fn){try{fn.run();fail("Forbidden read accepted");}catch(IllegalArgumentException expected){}}
    private ObjectNode installed(String tool,ObjectNode args){ObjectNode r=f.runs.create(request(),1);String id=r.path("runId").asText();ObjectNode step=obj().put("stepId","R").put("tool",tool).put("objective","read").put("executionMode","fixed").put("status","PENDING");step.set("dependsOn",arr());step.set("inputBindings",args);step.set("verificationRules",arr().add(obj().put("type","tool_success")));ObjectNode plan=obj();plan.set("steps",arr().add(step));plan.set("acceptanceCriteria",arr().add(obj().put("type","step_succeeded").put("stepId","R")));f.tx.execute(tx->{ObjectNode state=store.locked(id);state.set("plan",plan);state.put("planVersion",1).put("stepIndex",0).put("status","EXECUTING");store.save(state);return null;});return store.get(id);}
    private ObjectNode advance(ObjectNode run){String id=run.path("runId").asText();return f.tx.execute(tx->{ObjectNode state=store.locked(id);try{Method m=AgentRunService.class.getDeclaredMethod("advance",ObjectNode.class);m.setAccessible(true);m.invoke(f.runs,state);}catch(InvocationTargetException e){if(e.getCause() instanceof RuntimeException)throw(RuntimeException)e.getCause();throw new AssertionError(e);}catch(Exception e){throw new AssertionError(e);}store.save(state);return state;});}
    private ObjectNode read(){ObjectNode r=installed("read_display",obj().put("type","getRangeValue").put("sheetId","s").put("range","A1:D4"));advance(r);return advance(r);}
    public void testReadCompletesWithOneCallAndNoWorkbookOrEffectWrite(){ObjectNode before=f.runs.workspace(book,1),r=read();assertEquals("COMPLETED",r.path("status").asText());assertEquals(before.path("snapshot"),f.runs.workspace(book,1).path("snapshot"));assertEquals(before.path("draftVersion"),f.runs.workspace(book,1).path("draftVersion"));assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_tool_call where run_id=? and status='SUCCEEDED'",Integer.class,r.path("runId").asText()).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_effect where run_id=?",Integer.class,r.path("runId").asText()).intValue());assertEquals(1,f.runs.readDisplayResults(r.path("runId").asText(),1).path("items").size());}
    public void testClosedGateAdmitsNoCallOrArtifact()throws Exception{A1TestFixture.inject(f.runs,"readDisplay",false);assertFalse(f.runs.availableTools().contains("read_display"));ObjectNode r=installed("read_display",obj().put("type","getMerges").put("sheetId","s"));reject(()->advance(r));assertEquals(0,f.db.queryForObject("select count(*) from ai_analysis_artifact where run_id=?",Integer.class,r.path("runId").asText()).intValue());}
    public void testAnotherUserCannotReadKnownRun(){ObjectNode r=read();reject(()->f.runs.readDisplayResults(r.path("runId").asText(),2));}
    public void testRevokedWorkbookOwnershipHidesReadResult(){ObjectNode r=read();f.db.update("update ai_workbook set user_id=2 where workbook_id=?",book);reject(()->f.runs.readDisplayResults(r.path("runId").asText(),1));}
    public void testForeignArtifactReferenceStillRejects(){ObjectNode first=read();book=f.seed(snapshot.toString());ObjectNode other=read();String ref=other.path("outputs").path("R").path("resultRef").asText();f.tx.execute(tx->{ObjectNode state=store.locked(first.path("runId").asText());((ObjectNode)state.path("outputs").path("R")).put("resultRef",ref);store.save(state);return null;});reject(()->f.runs.readDisplayResults(first.path("runId").asText(),1));}
    public void testHistoricalReadDoesNotRelaxCurrentWritebackSourceGuard(){ObjectNode r=read();String oldRef=r.path("outputs").path("R").path("resultRef").asText();f.tx.execute(tx->{ObjectNode state=store.locked(r.path("runId").asText());state.put("revision","a-later-run-revision");store.save(state);return null;});assertEquals(1,f.runs.readDisplayResults(r.path("runId").asText(),1).path("items").size());ObjectNode current=store.get(r.path("runId").asText());reject(()->store.artifactRecord(current,oldRef));}
    public void testWriteMasqueradingAsReadRejectsBeforeDispatch(){ObjectNode r=installed("read_display",obj().put("type","setCell").put("sheetId","s").put("range","A1").put("value",99));reject(()->advance(r));assertEquals(snapshot,f.runs.workspace(book,1).path("snapshot"));assertEquals(0,f.db.queryForObject("select count(*) from ai_analysis_artifact where run_id=?",Integer.class,r.path("runId").asText()).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call where run_id=?",Integer.class,r.path("runId").asText()).intValue());}
    public void testMalformedSelectionRollsBackRunAndLease(){ObjectNode q=request();q.set("readSelection",obj().put("sheetId","other").put("range","A1"));reject(()->f.runs.create(q,1));assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_run where workbook_id=?",Integer.class,book).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_lease where workbook_id=? and run_id is not null",Integer.class,book).intValue());}
    public void testGenericReadArtifactIsNotExposedAsDisplayResult(){ObjectNode r=installed("read_range",obj().put("sheetId","s").put("range","A1:B2"));advance(r);r=advance(r);assertEquals(0,f.runs.readDisplayResults(r.path("runId").asText(),1).path("items").size());}
    public void testMissingSelectionRejectsBeforeEvenAnEarlierRead(){ObjectNode r=installed("read_display",obj().put("type","getSelection").put("sheetId","s"));f.tx.execute(tx->{ObjectNode state=store.locked(r.path("runId").asText());ObjectNode earlier=((ObjectNode)state.path("plan").path("steps").get(0)).deepCopy();earlier.put("stepId","P").put("tool","read_range");earlier.set("inputBindings",obj().put("sheetId","s").put("range","A1"));((ArrayNode)state.path("plan").path("steps")).insert(0,earlier);((ArrayNode)state.path("plan").path("acceptanceCriteria")).add(obj().put("type","step_succeeded").put("stepId","P"));store.save(state);return null;});reject(()->advance(r));assertEquals(0,f.db.queryForObject("select count(*) from ai_analysis_artifact where run_id=?",Integer.class,r.path("runId").asText()).intValue());}
}
